package com.csust.eyediagnosis.workflow.persistence.repository;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.csust.eyediagnosis.workflow.persistence.entity.ExplanationSnapshotEntity; import com.csust.eyediagnosis.workflow.persistence.mapper.ExplanationSnapshotMapper; import org.springframework.stereotype.Repository; import java.util.Optional;
@Repository public class MybatisExplanationSnapshotRepository implements ExplanationSnapshotRepository { private final ExplanationSnapshotMapper mapper; public MybatisExplanationSnapshotRepository(ExplanationSnapshotMapper mapper){this.mapper=mapper;} public int insert(ExplanationSnapshotEntity e){return mapper.insert(e);} public Optional<ExplanationSnapshotEntity> findByWorkflowIdAndRevision(String id,long revision){return Optional.ofNullable(mapper.selectOne(new LambdaQueryWrapper<ExplanationSnapshotEntity>().eq(ExplanationSnapshotEntity::getWorkflowId,id).eq(ExplanationSnapshotEntity::getRevision,revision)));} }
